package io.tornado.optimization;
import io.tornado.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;
@Service public class ProfileSelectionService{private final StrategyHorizonProfileRepository profiles;private final AppSettingsRepository settings;public ProfileSelectionService(StrategyHorizonProfileRepository p,AppSettingsRepository s){profiles=p;settings=s;}
@Transactional public Selection apply(WalkForwardProfileSelector.CandidateEvaluation challenger,ProfileScope scope,Coin coin,String strategyCode,int strategyVersion,long horizon){AppSettings configuration=settings.findById(1).orElseThrow();int minimum=scope==ProfileScope.GLOBAL?configuration.getMinimumConfigurationSamples():configuration.getCoinProfileMinimumSamples();if(!challenger.eligible()||challenger.evidence().validationSamples()<minimum)return new Selection(false,"Insufficient chronological validation samples",null);String key=StrategyHorizonProfile.activeKey(scope,coin,strategyCode,strategyVersion,horizon);StrategyHorizonProfile current=profiles.findByActiveKey(key).orElse(null);double required=configuration.getProfileReplacementMinimumImprovementPercent().doubleValue();if(scope==ProfileScope.COIN_SPECIFIC){StrategyHorizonProfile global=profiles.findByActiveKey(StrategyHorizonProfile.activeKey(ProfileScope.GLOBAL,null,strategyCode,strategyVersion,horizon)).orElse(null);if(global!=null&&challenger.selectionScore()<global.getSelectionScore()+required)return new Selection(false,"Coin override did not materially beat the global profile",current);}if(current!=null&&current.getSelectionSource()!=ProfileSelectionSource.FALLBACK&&challenger.selectionScore()<current.getSelectionScore()+required)return new Selection(false,"Challenger improvement is below the replacement threshold",current);Instant now=Instant.now();int version=profiles.maximumVersion(scope,coin==null?null:coin.getId(),strategyCode,strategyVersion,horizon)+1;if(current!=null)current.supersede(now,"Replaced by profile version "+version+" after chronological validation");var c=challenger.configuration();StrategyHorizonProfile selected=profiles.save(StrategyHorizonProfile.selected(coin,scope,strategyCode,strategyVersion,horizon,c.timeframe(),c.parameterKey(),version,challenger.evidence(),"Selected without using the final chronological test block for ranking",now));return new Selection(true,"Profile selected",selected);}
 public record Selection(boolean changed,String reason,StrategyHorizonProfile profile){}
}
